/* Компоненты путешествия поверх существующей игровой механики. */
const reducedMotion=()=>window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
function powerPoint(completed=0){return `<div class="power-point" aria-label="Пройдено этапов: ${completed} из 5">${journeySteps.map((s,i)=>`<i class="power-petal ${i<completed?'lit':''}" style="--angle:${i*72}deg"></i>`).join('')}<span></span></div>`}
function sceneVisual(kind){if(kind==='body'||kind==='return')return `<div class="journey-visual ${kind}"><img src="./body-figure.png" alt="Силуэт тела">${['#ef3058','#f87932','#ffc23e','#53cd89','#66d0ef','#7364ef','#efdaff'].map((c,i)=>`<i class="scene-chakra" style="--color:${c};bottom:${26+i*8}%;--delay:${i*.2}s"></i>`).join('')}${kind==='return'?'<div class="return-threads"></div>':''}</div>`;return `<div class="journey-visual ${kind}"><div class="scene-symbol"></div>${Array.from({length:9},(_,i)=>`<i class="scene-ray" style="--angle:${i*40}deg"></i>`).join('')}</div>`}
const originalRender=renderGame;
renderGame=function(){originalRender();const entry=ge('journey-entry');entry.hidden=!(game.originalRequest&&['intro','intro2','intro3','intro4','intro5'].includes(game.stage));['level-intro','level2-intro','level3-intro','level5-intro'].forEach(id=>ge(id).hidden=true);if(!entry.hidden){const d=journeySteps[game.level];renderLevelEntry(entry);}const progress=ge('journey-progress');progress.hidden=game.stage!=='board';if(!progress.hidden){const completed=game.completedModules||Array.from({length:5},(_,i)=>i<game.level);progress.innerHTML=`${powerPoint(completed.filter(Boolean).length)}<div><span class="eyebrow">${game.level+1} / 5 · ${journeySteps[game.level].name}</span><strong>${journeySteps[game.level].question}</strong><small>Ключ — осознание · Энергия — ресурс для изменений</small></div>`;progress.style.setProperty('--power',Math.min(1,.15+(game.energy+directedEnergy())/40));}const portal=ge('board-cells').querySelector('[data-position="0"]');if(portal){portal.classList.add('living-portal');portal.classList.toggle('unlocked',canPassPortal());portal.setAttribute('aria-label',canPassPortal()?'Путь открыт. Портал':'Портал: условия еще не выполнены')}ge('board-note').textContent=game.level===3?'Собери ключ, заверши круг и накопи 25 ⚡, чтобы открыть путь к творению.':'Бросай кубик, исследуй отклик и сохраняй осознания. Портал откроется, когда условия этапа выполнены.';if(game.stage==='center'){ge('center-stage').querySelector('h2').textContent='МОЯ ТОЧКА СИЛЫ';let result=ge('final-journey-result');if(!result){result=document.createElement('div');result.id='final-journey-result';ge('center-stage').prepend(result)}result.innerHTML=powerPoint(5)+`<p><b>Мой запрос:</b> ${escapeHtml(currentRequest())}</p>${currentRequest()!==game.originalRequest?`<p><b>Первоначальный запрос:</b> ${escapeHtml(game.originalRequest)}</p><small>История изменений сохранена в журнале осознаний.</small>`:""}<p>${escapeHtml(personalResult(4))}</p><p>Собрано ${game.energy+directedEnergy()} ⚡ · Направлено ${directedEnergy()} ⚡</p>`;}}
function personalResult(level){const latest=game.insights.filter(i=>i.level===level).at(-1)?.text;return [game.finalInsight,game.trueNeed,game.guardianInsight||game.acceptanceInsight,game.returnGuardianInsight||latest,game.creationActions.at(-1)?.text||game.futureGuardianInsight||latest][level]||latest||game.acceptedCards.filter(c=>c.level===level).map(c=>c.title).slice(-3).join(' · ')||'Твои записи доступны в журнале осознаний.'}
function earnedOnStage(level){return game.energyHistory.filter(e=>e.kind==='earned'&&e.level===level).reduce((sum,e)=>sum+e.amount,0)}
function portalRequirements(){const level=game.level,items=[];if(game.laps[level]<1)items.push('Заверши полный круг');if(!game.keys[level])items.push('Получи Ключ у Хранителя');if(level===3&&game.energy<25)items.push(`Собери еще ${25-game.energy} ⚡`);return items}
showPortalChoice=function(){const d=journeySteps[game.level],ready=canPassPortal();if(!ready){showModal('Портал','ПУТЬ ЕЩЕ ФОРМИРУЕТСЯ',`<div class="portal-object"></div><p>${portalRequirements().map(escapeHtml).join(' · ')}</p>`,singleClose('ПРОДОЛЖИТЬ ИССЛЕДОВАНИЕ'));return}showModal('ШАГ ПРОЙДЕН',d.result,`<div class="stage-result"><small>Что я исследовала</small><p>${escapeHtml(personalResult(game.level))}</p><small>Мой запрос</small><p>${escapeHtml(currentRequest())}</p><div class="result-energy"><b>Энергия этапа: +${earnedOnStage(game.level)} ⚡</b><b>Всего собрано: ${game.energy+directedEnergy()} ⚡</b></div>${game.energyTrackingLegacy?'<small>Начисления этапов учитываются с обновления. Ранее собранная энергия сохранена в общем запасе.</small>':''}<h3>${d.bridge}</h3><div class="portal-object unlocked"></div><span class="eyebrow">ПУТЬ ОТКРЫТ</span></div>`,[{label:'ВОЙТИ В ПОРТАЛ',action:()=>transitionTo(game.level+1)},{label:'Остаться и продолжить исследование',secondary:true,action:closeModal}])}
transitionTo=function(nextLevel){if(moving||!canPassPortal())return;moving=true;pendingPortal=false;ge('game-modal').hidden=true;modalOpen=false;const screen=ge('transition-screen');screen.querySelector('.portal-glow').innerHTML='<div class="portal-object unlocked"></div>';ge('transition-title').textContent='ПУТЬ ОТКРЫТ';ge('transition-name').textContent=nextLevel===5?'МОЯ ТОЧКА СИЛЫ':journeySteps[nextLevel].name;ge('transition-path').textContent=nextLevel===5?'Пять этапов соединяются':`${journeySteps[game.level].name} → ${journeySteps[nextLevel].name}`;screen.hidden=false;screen.classList.add('portal-enter');ge('roll-button').disabled=true;setTimeout(()=>{game.completedModules||=Array.from({length:5},(_,i)=>i<game.level);game.completedModules[game.level]=true;if(nextLevel===5){game.stage='center';game.position=0}else{game.level=nextLevel;game.position=0;game.stage=['intro','intro2','intro3','intro4','intro5'][nextLevel]}moving=false;persist();screen.hidden=true;screen.classList.remove('portal-enter');renderGame()},reducedMotion()?100:journeyTiming.portal)}
function energyFlight(amount){const target=ge('journey-progress'),rect=target.getBoundingClientRect();if(!rect.width)return;const layer=document.createElement('div');layer.className='energy-flight';layer.setAttribute('aria-hidden','true');for(let i=0;i<9;i++){const dot=document.createElement('i');dot.style.cssText=`--dx:${rect.left+45-window.innerWidth/2}px;--dy:${rect.top+45-window.innerHeight*.55}px;--delay:${i*35}ms;left:${window.innerWidth/2+(i-4)*12}px;top:${window.innerHeight*.55}px`;layer.append(dot)}document.body.append(layer);target.classList.remove('energy-arrived');void target.offsetWidth;target.classList.add('energy-arrived');setTimeout(()=>layer.remove(),1400);const before=game.energy-amount;requestAnimationFrame(()=>{const b=ge('play-status').querySelectorAll('.status-pill')[1]?.querySelector('b');if(!b)return;let start;function frame(now){start??=now;const t=Math.min(1,(now-start)/800);if(b.isConnected)b.textContent=`⚡ ${Math.round(before+amount*t)}`;if(t<1)requestAnimationFrame(frame)}requestAnimationFrame(frame)})}
const originalHandle=handleCell;
handleCell=function(){const type=routeCells()[game.position].type;const board=ge('board');board.dataset.effect=type;setTimeout(()=>{if(board.dataset.effect===type)delete board.dataset.effect},1500);originalHandle()};
const originalKey=showKey;
showKey=function(){originalKey();ge('modal-title').textContent='ОСОЗНАНИЕ ПРИНЯТО';ge('modal-content').innerHTML='<div class="key-reveal key-journey"><span>⚿</span></div><p>Ключ — твое осознание. Он открывает новый путь, когда исследование этапа завершено.</p>';renderGame()};
const originalDraw=showDrawnCard;
showDrawnCard=function(card){originalDraw(card);ge('modal-content').dataset.effect=card.deck==='Другой взгляд'?'view':card.deck==='Тень ↔ Сила'?'shadow':card.deck==='Богини / Архетипы силы'?'support':'card'};
function startJourneyIntro(){
 if(game.originalRequest||game.introSeen)return;
 const screen=ge('journey-cinema');screen.hidden=false;ge('roll-button').disabled=true;
 let timer,index=-2;
 const finish=()=>{clearTimeout(timer);globalThis.SoundManager?.stop('intro');screen.hidden=true;game.introSeen=true;game.stage='request';persist();renderGame();ge('start-request').focus({preventScroll:true})};
 ge('journey-skip').onclick=finish;
 function scene(){
  const area=ge('cinema-scene');
  if(index===-2)area.innerHTML=`${powerPoint(0)}<h1>ТОЧКА СИЛЫ</h1><p>Путь от запроса к энергии и действию</p><h2>У тебя есть запрос.</h2>`;
  else if(index===-1)area.innerHTML=`${powerPoint(0)}<h2>ЧТО ДАЕТ «ТОЧКА СИЛЫ»?</h2><p>«Точка силы» помогает исследовать твой запрос через метод пяти шагов: увидеть, что происходит, понять свои истинные потребности, обнаружить скрытые внутренние силы, вернуть энергию и осознанно направить ее в желаемые изменения.</p><p>В результате ты не просто исследуешь проблему, а определяешь, куда направить свою энергию, чтобы двигаться к своим целям и улучшать важные сферы жизни.</p>`;
  else if(index<5){const d=journeySteps[index];area.innerHTML=`${sceneVisual(d.visual)}<span class="eyebrow">${index+1} / 5 · ${d.name}</span><h2>${index+1}. ${d.introQuestion||d.question}</h2><p>${d.intro}</p><div class="intro-collection">${powerPoint(index+1)}<small>+ ЭНЕРГИЯ</small><i class="collection-particle"></i></div>`}
  else if(index===5)area.innerHTML=`${powerPoint(5)}<h2>ПО ПУТИ ТЫ БУДЕШЬ СОБИРАТЬ</h2><p>⚡ ЭНЕРГИЮ<br>Для своих целей и изменений в этой игре.</p><p>🔑 КЛЮЧИ<br>Чтобы открывать новые этапы пути.</p><p>💎 КРИСТАЛЛЫ<br>Для накопления в профиле и обмена на подарки.</p>`;
  else area.innerHTML=`${powerPoint(5)}<h2>УВИДЕТЬ → ПОНЯТЬ → ПРИНЯТЬ → ВЕРНУТЬ → НАПРАВИТЬ</h2><p>Твоя Точка силы</p>`;
  globalThis.SoundManager?.stop('intro');globalThis.SoundManager?.play(index===-2?'intro':index===-1||index===5?'screenTransition':index<5?'stepReveal':'finalTransformation',{step:Math.max(0,index),group:'intro'});
  area.classList.remove('scene-in');void area.offsetWidth;area.classList.add('scene-in');
  if(index>5)timer=setTimeout(finish,journeyTiming.final);
  else{const duration=index===-2?journeyTiming.opening:index===-1?journeyTiming.benefit:journeyTiming.step;index++;timer=setTimeout(scene,duration)}
 }
 ge('cinema-scene').innerHTML=`<div class="cinema-welcome">${powerPoint(0)}<h1>ТОЧКА СИЛЫ</h1><p>Путь от запроса к энергии и действию</p><button type="button" class="cinema-start" id="cinema-start">ВОЙТИ В ИГРУ</button></div>`;
 ge('cinema-start').onclick=()=>{ge('cinema-start').disabled=true;globalThis.SoundManager?.unlock();scene()};
}
const entry=document.createElement('div');entry.id='journey-entry';entry.className='request-gate journey-entry';entry.hidden=true;ge('request-gate').after(entry);const progress=document.createElement('div');progress.id='journey-progress';progress.className='journey-progress';ge('game-play-content').prepend(progress);const cinema=document.createElement('section');cinema.id='journey-cinema';cinema.className='journey-cinema';cinema.hidden=true;cinema.setAttribute('aria-label','Пять шагов Точки силы');cinema.innerHTML='<button type="button" id="journey-skip">Пропустить</button><div id="cinema-scene"></div>';document.body.append(cinema);
ge('request-gate').querySelector('h2').textContent='С ЧЕМ ТЫ ВХОДИШЬ В ИГРУ?';ge('request-gate').querySelector('p').textContent='Сформулируй ситуацию, желание или вопрос, который хочешь исследовать.';ge('start-request').setAttribute('aria-label','Мой запрос');ge('start-request').placeholder='Мой запрос';ge('start-game').textContent='НАЧАТЬ ПУТЬ';
if(!game.energyTrackingStarted){game.energyTrackingLegacy=!!game.originalRequest;game.energyTrackingStarted=new Date().toISOString();persist()}
renderGame();startJourneyIntro();
/* Оценка «сейчас» не тратит игровые жетоны; осознанное направление сохраняет существующее подтверждение цели. */
const originalSphereTablet=showSphereTablet;
function wheelSvg(values){const n=lifeSpheres.length,c=160,r=110;const xy=(i,v=10)=>{const a=i*2*Math.PI/n-Math.PI/2;return [c+Math.cos(a)*r*v/10,c+Math.sin(a)*r*v/10]};return `<svg class="balance-wheel" viewBox="0 0 320 320" role="img" aria-label="Распределение внимания по сферам жизни">${[.25,.5,.75,1].map(v=>`<circle cx="160" cy="160" r="${r*v}"/>`).join('')}${lifeSpheres.map((s,i)=>{const [x,y]=xy(i);return `<line x1="160" y1="160" x2="${x}" y2="${y}"/><text x="${xy(i,12)[0]}" y="${xy(i,12)[1]}" text-anchor="middle">${i+1}</text>`}).join('')}<polygon points="${lifeSpheres.map((s,i)=>xy(i,values[s.id]||0).join(',')).join(' ')}"/></svg>`}
showSphereTablet=function(mode){if(mode!=='desired'&&!game.balanceCurrentCompleted){showCurrentBalance();return}originalSphereTablet();const top=document.createElement('div');top.className='wheel-tabs';top.innerHTML='<button type="button" id="balance-current-tab">1. Как сейчас</button><button type="button" id="balance-desired-tab">2. Куда направлю</button>';ge('modal-content').prepend(top);ge('modal-title').textContent='КОЛЕСО ЖИЗНИ';ge('balance-current-tab').onclick=showCurrentBalance;ge('balance-desired-tab').onclick=()=>showSphereTablet('desired');}
function showCurrentBalance(){game.balanceCurrent||={};const draft={...game.balanceCurrent};showModal('КОЛЕСО ЖИЗНИ · 1 / 2','Как сейчас распределена моя энергия?',`<p>Оцени, сколько внимания получает каждая сфера: от 0 до 10.</p><div id="balance-visual">${wheelSvg(draft)}</div>${lifeSpheres.map((s,i)=>`<label class="balance-row" for="balance-${s.id}"><span>${i+1}. ${escapeHtml(s.name)}</span><input id="balance-${s.id}" type="range" min="0" max="10" step="1" value="${draft[s.id]||0}" data-balance="${s.id}"><output>${draft[s.id]||0}</output></label>`).join('')}<p class="balance-note">Это твоя оценка внимания. Игровой запас ${game.energy+directedEnergy()} ⚡ остается доступным для целей.</p>`,[{label:'Сохранить и выбрать новое направление',action:()=>{game.balanceCurrent=draft;game.balanceCurrentCompleted=true;game.balanceHistory||=[];game.balanceHistory.push({values:{...draft},at:new Date().toISOString()});persist();showSphereTablet('desired')}},{label:'Вернуться к игре',secondary:true,action:closeModal}]);ge('modal-content').querySelectorAll('[data-balance]').forEach(input=>input.oninput=()=>{draft[input.dataset.balance]=Number(input.value);input.nextElementSibling.value=input.value;ge('balance-visual').innerHTML=wheelSvg(draft)})}
// Обработчики существующих кнопок были привязаны до загрузки компонента.
for(const id of ['spheres-button','center-spheres']){const old=ge(id),button=old.cloneNode(true);old.replaceWith(button);button.onclick=()=>showSphereTablet()}
// Вступление повторяется только после явно подтвержденной новой игры.
const originalPersist=persist;let journeyRequestWasPresent=!!game.originalRequest;
persist=function(){originalPersist();if(journeyRequestWasPresent&&!game.originalRequest){journeyRequestWasPresent=false;setTimeout(startJourneyIntro,0)}else if(game.originalRequest)journeyRequestWasPresent=true};

